const PHONE_RE = /\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}|\[PHONE_\d+\]/g;
const SKIP_RE = /^(dear|sincerely|thank you|thanks|regards|best|hello|hi)\b/i;

const CATEGORY_RULES = [
  ['permission_slip', /permission|field trip|consent|slip\b/gi, 'Permission slip'],
  ['payment', /\$|\bfees?\b|\bpay\b|tuition|fundrais|balance/gi, 'Payment notice'],
  ['health', /vaccin|immuniz|nurse|illness|health|\bflu\b|lice|medic|screening/gi, 'Health notice'],
  ['meeting', /conference|meeting|parent[- ]teacher|\bPTA\b|open house|back to school night/gi, 'Meeting notice'],
  ['event', /concert|picnic|assembly|performance|festival|party|\bgame\b|dance|\bfair\b/gi, 'Event notice'],
  ['transportation', /\bbus\b|pick[- ]?up|drop[- ]?off|carpool|route/gi, 'Transportation notice'],
  ['policy', /policy|handbook|dress code|attendance|code of conduct|\brules?\b/gi, 'Policy update'],
  ['deadline', /deadline|\bdue\b|register|enroll|apply|renew/gi, 'Deadline notice'],
];

const JARGON = {
  'early release': 'School ends earlier than usual that day.',
  'half day': 'School is open only for part of the day.',
  'minimum day': 'School ends earlier than usual that day.',
  'permission slip': 'A form a parent signs to let the child take part.',
  chaperone: 'An adult who goes with the students to help watch them.',
  tardy: 'Arriving late to school or class.',
  truancy: 'Missing school without an excuse.',
  iep: 'A written plan for extra help for a student with a disability.',
  '504 plan': 'A plan that gives a student with a disability fair access to learning.',
  pta: 'Parent-Teacher Association: a group of parents and teachers who help the school.',
  pto: 'Parent-Teacher Organization: a group of parents and teachers who help the school.',
  ferpa: 'A law that protects the privacy of student records.',
  waiver: 'A paper where you agree to something or give up a right.',
  rsvp: 'Please tell the school if you are coming.',
  'free and reduced lunch': 'A program that gives free or cheaper school meals to families who qualify.',
  'immunization record': 'Paper from the doctor that shows the child got their vaccines.',
  'progress report': 'A paper that shows how the student is doing in class.',
  'report card': 'A paper that shows the final grades for a period.',
};

const QUESTION_BANK = {
  language: 'Can I get this notice, and an interpreter, in my language?',
  pay: 'Is there help if I cannot afford this cost? Can I pay another way?',
  sign: 'Do I need to send back a paper copy, or can I sign online?',
  event: 'Will there be child care or an interpreter at this event?',
};

function pickTitle(lines, category) {
  const first = lines[0] || '';
  if (first && first.length <= 100 && !/^(dear|hello|hi)\b/i.test(first) && !/[.!?]$/.test(first)) return first;
  const rule = CATEGORY_RULES.find((r) => r[0] === category);
  return rule ? rule[2] : 'School notice';
}

function cleanTask(sentence) {
  let t = sentence.replace(/^(please|kindly)\s+/i, '').replace(/\s+/g, ' ').trim();
  t = t.charAt(0).toUpperCase() + t.slice(1);
  return t.length > 220 ? `${t.slice(0, 217)}…` : t;
}

function actionType(s) {
  if (/\bsign/i.test(s)) return 'sign';
  if (/\bpay\b|\$|\bfee\b|\bcost\b/i.test(s)) return 'pay';
  if (/rsvp|register|sign up|confirm|reply|respond/i.test(s)) return 'rsvp';
  if (/\bbring|\bpack|\bwear/i.test(s)) return 'bring';
  if (/return|submit|turn in|send|complete|fill out|apply|renew|provide|update/i.test(s)) return 'submit';
  if (/attend|join|come to/i.test(s)) return 'attend';
  if (/online|website|portal|link/i.test(s)) return 'online';
  return 'other';
}

function priorityFor(sentence, dueIso, today) {
  const days = dueIso ? Math.round((Date.parse(`${dueIso}T00:00:00Z`) - Date.parse(`${today}T00:00:00Z`)) / 864e5) : null;
  if (/\b(required|must|mandatory|last day|urgent|immediately|asap)\b/i.test(sentence)) return days !== null && days > 14 ? 'medium' : 'high';
  if (days === null) return 'low';
  if (days <= 3) return 'high';
  if (days <= 10) return 'medium';
  return 'low';
}

function analyzeOffline(text, { today } = {}) {
  today = /^\d{4}-\d{2}-\d{2}$/.test(today || '') ? today : new Date().toISOString().slice(0, 10);
  const clean = String(text || '').replace(/\r/g, '').trim();
  const lines = clean.split('\n').map((l) => l.trim()).filter(Boolean);
  const sentences = splitSentences(clean).filter((x) => (!SKIP_RE.test(x) || x.split(/\s+/).length > 8) && !(lines.length > 1 && x === lines[0] && x.length <= 100 && !/[.!?]$/.test(x)));

  // Category
  let category = 'other';
  let best = 0;
  for (const [cat, re] of CATEGORY_RULES) {
    const hits = (clean.match(re) || []).length;
    if (hits > best) {
      best = hits;
      category = cat;
    }
  }

  const actions = [];
  const events = [];
  const bring = [];
  const money = [];
  const keySentences = [];

  for (const sentence of sentences) {
    const dates = findDates(sentence, today);
    const times = findTimes(sentence);
    const monies = sentence.match(MONEY_RE) || [];
    const actionLike = isAction(sentence);
    const isEvent = EVENT_RE.test(sentence) && (dates.length > 0 || times.start);

    if (monies.length) monies.forEach((amount) => money.push({ amount: amount.replace(/\s+/g, ''), purpose: cleanTask(sentence).slice(0, 160), due_date: dates[0] ? dates[0].iso : null }));
    if (/\b(bring|pack|wear)\b/i.test(sentence)) bring.push(cleanTask(sentence));

    if (actionLike && !(isEvent && !/\b(return|sign|submit|rsvp|register|pay|confirm|complete)\b/i.test(sentence))) {
      const due = dates[0] ? dates[0].iso : null;
      actions.push({
        task: cleanTask(sentence),
        due_date: due,
        due_text: dates[0] ? dates[0].raw : '',
        priority: priorityFor(sentence, due, today),
        type: actionType(sentence),
      });
      keySentences.push(sentence);
    } else if (isEvent && dates[0]) {
      events.push({ title: cleanTask(sentence).slice(0, 90), date: dates[0].iso, start_time: times.start, end_time: times.end, location: '', notes: '' });
      keySentences.push(sentence);
    } else if (dates.length || monies.length) {
      keySentences.push(sentence);
    }
  }

  actions.sort((a, b) => (a.due_date || '9999').localeCompare(b.due_date || '9999'));

  const contacts = [];
  const emails = [...new Set(clean.match(EMAIL_RE) || [])];
  const phones = [...new Set(clean.match(PHONE_RE) || [])];
  const personRe = /(?<![-\w])(?:Ms|Mr|Mrs|Dr|Nurse|Principal|Coach|Counselor)\.?\s+[A-Z][a-z]+(?:\s+[A-Z][a-z]+)?/g;
  const people = [...new Set(clean.match(personRe) || [])];
  emails.forEach((email, i) => contacts.push({ name: people[i] || '', role: '', email, phone: i === 0 ? phones[0] || '' : '' }));
  if (!emails.length && phones.length) contacts.push({ name: people[0] || '', role: '', email: '', phone: phones[0] });

  const schoolMatch = /([A-Z][A-Za-z]+(?:\s+[A-Z][A-Za-z]+)*\s+(?:Elementary|Middle School|High School|Academy|School District|School))/.exec(clean);
  const sender = (schoolMatch && schoolMatch[1]) || people[people.length - 1] || '';

  const lower = clean.toLowerCase();
  const glossary = Object.keys(JARGON)
    .filter((k) => lower.includes(k))
    .slice(0, 8)
    .map((k) => ({ term: k, plain: JARGON[k] }));

  const summarySource = (keySentences.length ? keySentences : sentences).slice(0, 3);
  const summary = summarySource.map((x) => cleanTask(x)).join(' ');

  const nearest = actions.concat(events.map((e) => ({ due_date: e.date }))).map((x) => x.due_date).filter(Boolean).sort()[0];
  const days = nearest ? Math.round((Date.parse(`${nearest}T00:00:00Z`) - Date.parse(`${today}T00:00:00Z`)) / 864e5) : null;
  let urgency = 'low';
  if (/\b(urgent|immediately|asap)\b/i.test(clean) || (days !== null && days >= 0 && days <= 3)) urgency = 'high';
  else if (days !== null && days >= 0 && days <= 10) urgency = 'medium';

  const questions = [QUESTION_BANK.language];
  if (money.length) questions.push(QUESTION_BANK.pay);
  if (actions.some((a) => a.type === 'sign')) questions.push(QUESTION_BANK.sign);
  if (events.length) questions.push(QUESTION_BANK.event);

  const uncertain = ['Demo mode: this summary was extracted by rules, not by AI, and it is not translated. Add an API key for translation and deeper understanding.'];
  if (!actions.length && !events.length) uncertain.push('No clear deadlines or events were found. Read the original notice carefully.');

  const title = pickTitle(lines, category);
  return normalizeAnalysis({
    title,
    title_en: title,
    sender,
    category,
    urgency,
    detected_language: 'English',
    summary,
    summary_en: summary,
    key_points: [...new Set(keySentences)].slice(0, 5).map((x) => cleanTask(x).slice(0, 160)),
    actions,
    events,
    money,
    bring: [...new Set(bring)],
    contacts,
    glossary,
    questions_to_ask: questions,
    uncertain,
    confidence: 0.5,
  });
}

module.exports = { analyzeOffline, findDates, findTimes, splitSentences, ACTION_RE, JARGON };

